/* Standalone item master. Stable ids are referenced by SOP steps. */
let itemFilter={module:'',category:'',subcategory:'',search:'',status:'active'};
function scrubLeakedFixtureCategories(){if(!state.itemCategories)return;const leaked=new Set(['Judge Supplies','Judge Needles']);const blocked=new Set(state.itemCategories.filter(c=>leaked.has(c.name)).map(c=>c.id));if(!blocked.size)return;state.itemCategories=state.itemCategories.filter(c=>!blocked.has(c.id)&&!blocked.has(c.parentId));if(state.items)state.items=state.items.filter(i=>!blocked.has(i.categoryId)&&!blocked.has(i.subcategoryId));if(blocked.has(itemFilter.category)||blocked.has(itemFilter.subcategory)){itemFilter.category='';itemFilter.subcategory='';}}
function ensureItemState(){if(!state.itemCategories)state.itemCategories=[{id:'cat-health-medicines',name:'Medicines',module:'Health',parentId:null},{id:'sub-health-treatment',name:'Approved treatments',module:'Health',parentId:'cat-health-medicines'},{id:'cat-pc-vaccines',name:'Vaccines',module:'Preventive Care',parentId:null},{id:'sub-pc-routine',name:'Routine vaccination',module:'Preventive Care',parentId:'cat-pc-vaccines'},{id:'cat-feed-nutrition',name:'Nutrition',module:'Feed',parentId:null},{id:'sub-feed-dry',name:'Dry feed',module:'Feed',parentId:'cat-feed-nutrition'},{id:'cat-proc-equipment',name:'Equipment',module:'Procurement',parentId:null},{id:'sub-proc-measuring',name:'Measuring devices',module:'Procurement',parentId:'cat-proc-equipment'}];if(!state.items){state.items=[{id:'item-treatment-a',name:'Vet-approved treatment A',module:'Health',categoryId:'cat-health-medicines',subcategoryId:'sub-health-treatment',description:'Illustrative catalogue entry. Clinical protocol is defined by the veterinarian.',purpose:'Reference a vet-approved treatment protocol.',unit:'unit',active:true,shares:['Procurement','Preventive Care']},{id:'item-treatment-b',name:'Vet-approved treatment B',module:'Health',categoryId:'cat-health-medicines',subcategoryId:'sub-health-treatment',description:'Illustrative alternative treatment reference; no dose is prescribed here.',purpose:'Reference an alternative approved protocol.',unit:'unit',active:true,shares:['Procurement']},{id:'item-vaccine-a',name:'Approved vaccine reference A',module:'Preventive Care',categoryId:'cat-pc-vaccines',subcategoryId:'sub-pc-routine',description:'Demonstration vaccine record. Batch and clinical administration details belong to execution.',purpose:'Select an approved vaccination item.',unit:'vial',active:true,shares:['Health','Procurement']},{id:'item-feed-pellets',name:'Grower feed pellets',module:'Feed',categoryId:'cat-feed-nutrition',subcategoryId:'sub-feed-dry',description:'Illustrative feed catalogue item.',purpose:'Record feed purchase and consumption.',unit:'kg',active:true,shares:['Procurement']},{id:'item-feed-hay',name:'Dry hay',module:'Feed',categoryId:'cat-feed-nutrition',subcategoryId:'sub-feed-dry',description:'Illustrative forage item.',purpose:'Record forage requirements.',unit:'kg',active:true,shares:['Procurement']},{id:'item-thermometer',name:'Digital thermometer',module:'Procurement',categoryId:'cat-proc-equipment',subcategoryId:'sub-proc-measuring',description:'Illustrative equipment reference.',purpose:'Select the instrument used for a measurement.',unit:'piece',active:true,shares:['Health','Preventive Care']}];if(state.shared?.medicines){state.items.filter(i=>i.categoryId==='cat-health-medicines').forEach(i=>i.shares=state.shared.medicines.filter(m=>m!=='Health'))}}state.items.forEach(i=>{i.revision??=1});const lifecyclePurposeUpdates={'Adult female valuation rate': 'Rate for a selected lifecycle stage; stage CRUD lives in Counts registers', 'Adult female assumed weight': 'Default weight for a selected lifecycle stage; stage CRUD lives in Counts registers', 'Adult male / buck valuation rate': 'Rate for a selected lifecycle stage; stage CRUD lives in Counts registers', 'Adult male / buck assumed weight': 'Default weight for a selected lifecycle stage; stage CRUD lives in Counts registers', 'K0 valuation rate': 'Rate setting for a selected lifecycle stage; the stage itself lives in Counts registers', 'K0 assumed weight': 'Default weight setting for a selected lifecycle stage; the stage itself lives in Counts registers', 'K1 valuation rate': 'Rate setting for a selected lifecycle stage; the stage itself lives in Counts registers', 'K1 assumed weight': 'Default weight setting for a selected lifecycle stage; the stage itself lives in Counts registers', 'K2 valuation rate': 'Rate setting for a selected lifecycle stage; the stage itself lives in Counts registers', 'K2 assumed weight': 'Default weight setting for a selected lifecycle stage; the stage itself lives in Counts registers', 'K3 valuation rate': 'Rate setting for a selected lifecycle stage; the stage itself lives in Counts registers', 'K3 assumed weight': 'Default weight setting for a selected lifecycle stage; the stage itself lives in Counts registers'};state.items.forEach(i=>{if(lifecyclePurposeUpdates[i.name])i.purpose=lifecyclePurposeUpdates[i.name];});scrubLeakedFixtureCategories();}
function itemById(id){ensureItemState();return state.items.find(i=>i.id===id)}function availableItems(module){ensureItemState();return state.items.filter(i=>i.active&&(i.module===module||i.shares.includes(module)))}function itemCategory(id){return state.itemCategories.find(c=>c.id===id)}function itemCategoryName(id){return itemCategory(id)?.name||'—'}function normalizeItemFilter(){if(itemFilter.category&&!itemCategory(itemFilter.category))itemFilter.category='';if(itemFilter.subcategory&&!itemCategory(itemFilter.subcategory))itemFilter.subcategory='';if(itemFilter.category&&itemCategory(itemFilter.category)?.module!==itemFilter.module)itemFilter.category='';if(itemFilter.subcategory&&itemCategory(itemFilter.subcategory)?.parentId!==itemFilter.category)itemFilter.subcategory='';}
function itemUsages(id){let usages=[];function check(s,module,kind,activeDraft=false){if(!s)return;let item=itemById(id);for(const n of s.nodes||[]){let direct=n.itemId===id||n.resourceId===id||n.medicine===item?.name;let catalogue=n.answer==='Catalogue'&&(!s.definition?(typeof nodeCatalogue==='function'?nodeCatalogue(n,module).some(i=>i.id===id):item&&(item.module===module||item.shares.includes(module))&&(!n.catalogModule||n.catalogModule===item.module)):(s.definition.catalogues?.[n.id]||[]).some(i=>i.id===id));let pinned=n.itemId===id&&!!s.definition?.items?.[id];if(direct||catalogue||pinned)usages.push({title:s.title,module,kind,nodeId:n.id,nodeLabel:n.label,nodeType:n.type,activeDraft})}}function workflow(s,m,label,active){check(s,m,label,active);check(s.published,m,'Published v'+s.version);(s.versions||[]).forEach(v=>check(v,m,'Published v'+v.version))}Object.entries(state.sops||{}).forEach(([m,s])=>workflow(s,m,'Draft',true));Object.entries(state.archivedSops||{}).forEach(([m,ss])=>ss.forEach(s=>workflow(s,m,'Workflow draft',false)));return usages}
function openItemUsage(itemId,index){let u=itemUsages(itemId).filter(u=>canEdit()||u.kind.startsWith('Published'))[index];if(!u)return;if(u.activeDraft){closeModal();go(u.module,'Editor');selected=u.nodeId;renderEditor()}else modal('Linked workflow reference',`<h2>${esc(u.title)}</h2><p>${esc(u.module)} · ${esc(u.kind)}</p><div class="notice">${esc(u.nodeType)}: ${esc(u.nodeLabel)}<br>Stable step reference: ${esc(u.nodeId)}</div><p>This reference belongs to an archived workflow or published snapshot. Its definition is retained independently of the current draft.</p><button onclick="itemModal('${itemId}')">Back to item</button>`)}
function setItemFilter(key,value){itemFilter[key]=value;if(key==='module'){itemFilter.category='';itemFilter.subcategory=''}if(key==='category')itemFilter.subcategory='';renderItems()}
function renderItems(){ensureItemState();normalizeItemFilter();let target=$('#main');target.innerHTML=`<div class="items-heading"><div><div class="eyebrow">CONFIGURATION</div><h1>Items and settings</h1><p>Reusable records and settings.</p></div><div class="actions"><button onclick="categoryModal()" ${!canEdit()?'disabled':''}>Organize groups</button><button class="primary" onclick="itemModal()" ${!canEdit()?'disabled':''}>+ Add item or setting</button></div></div><div class="item-stats"><span><b>${state.items.filter(i=>i.active).length}</b> active items</span><span><b>${new Set(state.items.map(i=>i.module)).size}</b> owner modules</span><span><b>${state.items.filter(i=>itemVisibleConsumers(i).length).length}</b> shared items</span></div><div class="items-workspace"><section class="items-tree"><div class="items-tree-title">ITEMS AND SETTINGS FILTERS</div><p class="items-tree-help">Reusable settings only. Modules are filters, not categories.</p><button class="${!itemFilter.module?'active':''}" onclick="setItemFilter('module','')">All reusable items <span>${state.items.length}</span></button>${modules.map(m=>`<button class="${itemFilter.module===m?'active':''}" onclick="setItemFilter('module','${m}')">${m}<span>${state.items.filter(i=>itemMatchesModule(i,m)).length}</span></button>`).join('')}</section><section class="items-results"><div class="items-filters"><input id="itemsearch" aria-label="Search items" placeholder="Search name, purpose, category…" value="${esc(itemFilter.search)}" oninput="itemFilter.search=this.value;renderItemRows()"><select aria-label="Item status" onchange="setItemFilter('status',this.value)"><option value="active" ${itemFilter.status==='active'?'selected':''}>Active items</option><option value="archived" ${itemFilter.status==='archived'?'selected':''}>Archived items</option><option value="all" ${itemFilter.status==='all'?'selected':''}>All statuses</option></select></div><div class="items-breadcrumb">${esc(itemFilter.module||'All reusable items')}</div><div class="tablewrap"><table class="items-table"><thead><tr><th>Item</th><th>Owner / used by</th><th>Unit</th><th>Available to</th><th>Status</th></tr></thead><tbody id="itemrows"></tbody></table></div><div class="notice" style="margin:16px">These are references for workflows. They do not create stock, animals or permissions.</div></section></div>`;renderItemRows()}
function renderItemRows(){let items=state.items.filter(i=>itemMatchesModule(i,itemFilter.module)&&(!itemFilter.category||i.categoryId===itemFilter.category)&&(!itemFilter.subcategory||i.subcategoryId===itemFilter.subcategory)&&(itemFilter.status==='all'||(itemFilter.status==='active'?i.active:!i.active))&&[i.name,i.description,i.purpose,itemCategoryName(i.categoryId),itemCategoryName(i.subcategoryId)].join(' ').toLowerCase().includes(itemFilter.search.toLowerCase()));$('#itemrows').innerHTML=items.map(i=>`<tr class="item-click-row" tabindex="0" onclick="itemModal('${i.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();itemModal('${i.id}')}"><td><strong>${esc(i.name)}</strong><div class="muted">${esc(i.purpose)}</div></td><td><b>${esc(i.module||'Shared')}</b><div class="muted">${esc(itemVisibleConsumers(i).length?'Used by '+itemVisibleConsumers(i).join(' · '):'Only in '+(i.module||'Shared'))}</div></td><td>${esc(i.unit)}</td><td><div class="item-share-tags"><span class="badge">${i.module}</span>${itemVisibleConsumers(i).map(m=>`<span class="badge blue">${m}</span>`).join('')}</div></td><td><span class="badge ${i.active?'':'amber'}">${i.active?'Active':'Archived'}</span></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No items match these filters. Try another vertical or create an item.</div></td></tr>'}
function itemModal(id){ensureItemState();let i=id?itemById(id):{name:'',module:itemFilter.module||'Health',categoryId:itemFilter.category||'',subcategoryId:itemFilter.subcategory||'',description:'',purpose:'',unit:'unit',active:true,shares:[]};let usages=id?itemUsages(id).filter(u=>canEdit()||u.kind.startsWith('Published')):[],dis=!canEdit()?'disabled':'';modal(id?'Item details':'Add item or setting',`<div class="item-drawer-intro">${id?`Stable reference: ${esc(id)} · Revision ${i.revision}`:'Create one reusable item or setting'}</div><form id="itemform" onsubmit="event.preventDefault();saveItem('${id||''}')"><label class="field"><span>Item name</span><input id="iname" required maxlength="120" value="${esc(i.name)}" ${dis}></label><div class="inputrow"><label class="field"><span>Owned by business area</span><select id="imodule" onchange="refreshItemCategories()" ${dis}>${modules.map(m=>`<option ${i.module===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="field"><span>Unit</span><select id="iunit" ${dis}>${['unit','piece','kg','g','ml','litre','vial','pack','bag','source unspecified'].map(u=>`<option ${i.unit===u?'selected':''}>${u}</option>`).join('')}</select></label></div><div class="inputrow"><label class="field"><span>Group</span><select id="icategory" onchange="refreshItemSubcategories()" required ${dis}></select></label><label class="field"><span>Type</span><select id="isubcategory" required ${dis}></select></label></div><label class="field"><span>Purpose</span><input id="ipurpose" value="${esc(i.purpose)}" placeholder="What is this item used for?" required ${dis}></label><label class="field"><span>Description</span><textarea id="idescription" rows="2" ${dis}>${esc(i.description)}</textarea></label><label class="field"><span>Status</span><select id="iactive" ${dis}><option value="true" ${i.active?'selected':''}>Active · available in new work instructions</option><option value="false" ${!i.active?'selected':''}>Archived · keep past use</option></select></label><div id="itemshares" class="item-share-grid">${modules.map(m=>`<label class="checkrow"><input type="checkbox" data-item-share="${m}" ${i.shares.includes(m)||i.module===m?'checked':''} ${dis||i.module===m?'disabled':''}>${m}</label>`).join('')}</div>${id?`<div class="item-usage"><h3>Where it appears</h3>${usages.map((u,index)=>`<button type="button" class="linkline item-usage-row" onclick="openItemUsage('${id}',${index})"><span><strong>${esc(u.title)}</strong><br><span class="muted">${u.module} · ${esc(u.nodeType)}: ${esc(u.nodeLabel)}</span></span><span class="badge blue">${u.kind}</span></button>`).join('')||'<p class="muted">This item is not used in a work instruction yet.</p>'}</div>`:''}<div id="itemerror" class="error"></div><div class="actions item-drawer-footer"><button type="button" onclick="closeModal()">Cancel</button><div class="spacer"></div><button class="primary" type="submit" ${dis}>${id?'Save item changes':'Create item'}</button></div></form>`,true);$('.modal').classList.add('item-drawer');refreshItemCategories(i.categoryId,i.subcategoryId)}
function refreshItemCategories(cat,sub){let m=$('#imodule').value,categories=state.itemCategories.filter(c=>c.module===m&&!c.parentId);$('#icategory').innerHTML='<option value="">Choose category…</option>'+categories.map(c=>`<option value="${c.id}" ${cat===c.id?'selected':''}>${esc(c.name)}</option>`).join('');refreshItemSubcategories(sub);document.querySelectorAll('[data-item-share]').forEach(el=>{el.disabled=!canEdit()||el.dataset.itemShare===m;if(el.dataset.itemShare===m)el.checked=true})}
function refreshItemSubcategories(sub){let cat=$('#icategory').value;$('#isubcategory').innerHTML='<option value="">Choose subcategory…</option>'+state.itemCategories.filter(c=>c.parentId===cat).map(c=>`<option value="${c.id}" ${sub===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}
function saveItem(id){if(!canEdit())return;let old=id?itemById(id):null,i={id:id||'item-'+crypto.randomUUID(),revision:(old?.revision||0)+1,name:$('#iname').value.trim(),module:$('#imodule').value,categoryId:$('#icategory').value,subcategoryId:$('#isubcategory').value,purpose:$('#ipurpose').value.trim(),description:$('#idescription').value.trim(),unit:$('#iunit').value,active:$('#iactive').value==='true',shares:[...document.querySelectorAll('[data-item-share]:checked')].map(el=>el.dataset.itemShare).filter(m=>m!==$('#imodule').value)};let cat=itemCategory(i.categoryId),sub=itemCategory(i.subcategoryId);if(!i.name||!i.purpose||!cat||cat.module!==i.module||!sub||sub.parentId!==cat.id){$('#itemerror').textContent='Enter a name and purpose, then choose a category and subcategory for the owning module.';return}if(state.items.some(x=>x.id!==i.id&&x.module===i.module&&x.name.toLowerCase()===i.name.toLowerCase())){$('#itemerror').textContent='An item with this name already exists for this owner module.';return}let removed=old&&old.shares.filter(m=>!i.shares.includes(m)),affected=old?itemUsages(id).filter(u=>(old.active&&!i.active)||(old.module!==i.module)||(removed.includes(u.module))):[];if(affected.length){window.pendingItemSave=i;modal('Review impact before saving',`<div class="notice">This change affects ${affected.length} work instruction steps. Drafts and new publications may require a new item. Previously published instructions keep the version they used.</div>${affected.map(u=>`<div class="linkline"><span>${esc(u.title)}<br><span class="muted">${esc(u.nodeType)}: ${esc(u.nodeLabel)}</span></span><span class="muted">${u.module} · ${u.kind}</span></div>`).join('')}<div class="actions" style="margin-top:22px"><button onclick="itemModal('${id}')">Discard changes and return</button><button class="primary" onclick="commitItem(window.pendingItemSave)">Save with impact acknowledged</button></div>`);return}commitItem(i)}
function commitItem(i){if(!canEdit()||!i)return;let idx=state.items.findIndex(x=>x.id===i.id);if(idx<0)state.items.push(i);else state.items[idx]=i;record((idx<0?'Created item: ':'Updated item: ')+i.name);closeModal();renderItems();toast('Item saved in this browser')}
function categoryModal(){ensureItemState();modal('Organize item groups',`<p>Use this only to group reusable item/setting choices. Modules are owners or consumers, not categories. Parks, pens, species, breeds, lifecycle stages, tags and animals stay in Farm and animal registers.</p><label class="field"><span>Owner / used by module</span><select id="hmodule" onchange="renderHierarchyEditor()">${modules.map(m=>`<option ${m===(itemFilter.module||'Health')?'selected':''}>${m}</option>`).join('')}</select></label><div id="hierarchyeditor"></div>`,true);renderHierarchyEditor()}
function renderHierarchyEditor(){let m=$('#hmodule').value;$('#hierarchyeditor').innerHTML=`${state.itemCategories.filter(c=>c.module===m&&!c.parentId).map(c=>`<div class="item-hierarchy-row"><div class="inputrow"><input id="rename-${c.id}" aria-label="Group name" value="${esc(c.name)}"><button onclick="renameCategory('${c.id}')">Rename</button></div>${state.itemCategories.filter(sub=>sub.parentId===c.id).map(sub=>`<div class="inputrow item-sub-edit"><input id="rename-${sub.id}" aria-label="Subcategory name" value="${esc(sub.name)}"><button onclick="renameCategory('${sub.id}')">Rename</button></div>`).join('')}<div class="inputrow item-sub-edit"><input id="add-${c.id}" aria-label="New type for ${esc(c.name)}" placeholder="New type name"><button onclick="addItemCategory('${c.id}')">+ Add subcategory</button></div></div>`).join('')}<div class="inputrow" style="margin-top:22px"><input id="add-root" aria-label="New category name" placeholder="New category name"><button class="primary" onclick="addItemCategory()">+ Add category</button></div>`}
function addItemCategory(parentId){if(!canEdit())return;let name=$('#add-'+(parentId||'root')).value.trim(),module=$('#hmodule').value;if(!name)return toast('Enter a category name');if(state.itemCategories.some(c=>c.module===module&&(c.parentId||null)===(parentId||null)&&c.name.toLowerCase()===name.toLowerCase()))return toast('This category name already exists here');state.itemCategories.push({id:'category-'+crypto.randomUUID(),name,module,parentId:parentId||null});record('Added item '+(parentId?'subcategory: ':'category: ')+name);renderHierarchyEditor();toast('Hierarchy saved locally')}
function renameCategory(id){if(!canEdit())return;let c=itemCategory(id),name=$('#rename-'+id).value.trim();if(!name)return toast('Enter a category name');if(state.itemCategories.some(x=>x.id!==id&&x.module===c.module&&x.parentId===c.parentId&&x.name.toLowerCase()===name.toLowerCase()))return toast('This category name already exists here');c.name=name;record('Renamed item category: '+name);renderHierarchyEditor();toast('Category renamed; item references preserved')}

function itemVisibleConsumers(i){return [...new Set([...(i.shares||[]),...(state.dataSources||[]).filter(s=>s.kind==='items'&&s.owner===i.module&&s.categoryId===i.categoryId).flatMap(s=>s.shares||[])])].filter(m=>m!==i.module)}

function itemMatchesModule(item,module){if(!module)return true;if(module==='Common')return item.module==='Common';if(typeof genericItemAccess==='function')return genericItemAccess(item).some(a=>a.module===module);return item.module===module||itemVisibleConsumers(item).includes(module);}
